def refs():
    return [{**s, "subject": "science", "locator": "植物蒸散與葉片數量／溫度資料、植物分布與水流、樹冠遮蔭與微氣候、空氣污染與測量、控制變因與替代解釋", "observedPattern": "公開學校自然科題組常以表格、蒸散裝置、溫度或空氣品質情境要求比較資料、辨認控制變因並限制推論；本題將能力方向改寫為校園植物分布對水流、氣溫與空氣品質的原創探究題。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-db-iv-8-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": "A", "explanation": explanation + "選 A。"}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開自然／生物資料僅供蒸散資料比較、植物分布與水流、溫度微氣候、空氣污染與公平測量的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公立學校公開自然／生物資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "下雨時，校園樹冠對雨水路徑的影響，哪項描述最完整？", {"A": "部分雨水可暫留葉面、沿枝幹流下或滴落，另有部分到達地面後入滲或形成逕流", "B": "所有雨水都被葉片吸收，不會到達土壤", "C": "樹冠只會讓雨水立刻蒸發，與枝幹和土壤無關", "D": "只要有植物，地表就不可能產生逕流"}, "樹冠會改變降雨到達地面的時間與位置，但雨水仍可能沿枝幹流下、滴落、入滲或形成逕流；植物多不等於水永遠消失。", "水流題先畫雨水可能的多條路徑，再區分暫存、入滲與逕流。", ["先找降雨接觸的葉面與枝幹。", "列出暫留、枝幹流、滴落等到達地面的方式。", "確認根系與土壤孔隙可能促進入滲。", "保留坡度與地表材質造成逕流的可能。", "所以選 A。"], "easy"),
    make(2, "比較有樹蔭與無樹蔭地面的溫度時，哪種設計較公平？", {"A": "在相同時間、測量高度與天氣下，選材質和坡向相近的地面，只比較是否受樹冠遮蔭", "B": "樹蔭區在中午量測，無樹蔭區在清晨量測", "C": "一區測地面溫度，另一區測樹葉溫度，再直接比較", "D": "只挑最涼的樹下與最熱的柏油路，不記錄日照與材質"}, "溫度比較需要固定時間、測量高度、天氣、地表材質與坡向等條件，才能把差異較合理地連到樹冠遮蔭。", "公平測試採固定條件、單一主要變因、相同測量指標的順序。", ["指定主要變因為是否受樹冠遮蔭。", "固定時間、測量高度、日照、材質與坡向。", "使用相同溫度工具與記錄方式。", "避免跨時段、跨材質與挑極端點造成混淆。", "所以選 A。"], "easy"),
    make(3, "樹冠遮蔭和蒸散可能降低附近地表溫度，但下列哪項仍需額外測量？", {"A": "植物造成的降溫量是否大於風速、地表材質與建築遮蔽等其他因素的影響", "B": "樹葉是否具有任何顏色", "C": "植物一定能讓整個城市各處溫度相同", "D": "只要有樹就可排除所有熱源"}, "觀察到樹下較涼只能呈現相關；風速、地表材料、建築遮蔽與熱源都可能影響溫度，需設計對照與重複測量才能分辨。", "因果判讀先列替代解釋，再設計可排除它們的測量。", ["記錄樹下與對照地點的溫度差。", "列出風速、材質、建築遮蔽與熱源等替代因素。", "安排相似地點與相同時間的對照。", "用重複資料估計植物作用，而不是直接宣稱全城降溫。", "所以選 A。"], "medium"),
    make(4, "若研究植物分布對雨後逕流的影響，哪個指標最直接？", {"A": "相同降雨量與時間下，記錄有植被與無植被地區的逕流量、入滲量與土壤含水量", "B": "只數兩區有幾棵樹，不測量雨量或水流", "C": "只詢問居民覺得哪區比較不淹水", "D": "把植物高度直接當成逕流量，不觀察地面坡度"}, "逕流、入滲與土壤含水量是水路徑的直接指標；樹數或主觀感受不能取代相同降雨條件下的水量資料。", "先把概念轉成可量測變數，再補上相同降雨與地形條件。", ["確認研究問題是雨後水的去向。", "選擇逕流量、入滲量與土壤含水量作指標。", "固定降雨量、觀測時間、坡度與地表材質。", "比較有植被與無植被資料，避免只用樹高代替水量。", "所以選 A。"], "medium"),
    make(5, "植物可能攔截部分懸浮微粒，因此比較道路旁與校園內空氣品質時，哪項最重要？", {"A": "同時記錄風向、風速、距離排放源、植物種類與測量高度，並設置多個測點", "B": "只測一棵樹背風側一次，就代表整個校園", "C": "只看樹葉顏色，不量測空氣中的粒狀物", "D": "只要植物多，便可忽略車流與工地排放"}, "空氣品質受風向、風速、污染源距離、植物結構與測量位置共同影響，多測點與條件紀錄才能避免把單一結果誇大。", "空氣資料題先確認空間與時間條件，再控制排放源與風場的差異。", ["辨認要比較的是懸浮微粒或其他空氣指標。", "列出風向、風速、排放源距離與測量高度。", "設置道路旁、植物帶內與背景區等多測點。", "重複量測後才評估植物攔截的可能作用。", "所以選 A。"], "hard"),
    make(6, "若樹帶使狹窄街道的懸浮微粒較低，但無風時污染物仍累積，最合理的解釋是？", {"A": "植物攔截可能降低部分粒狀物，但通風與排放量仍會影響污染物是否累積", "B": "植物可把所有污染物完全分解，所以資料一定互相矛盾", "C": "只要空氣不流動，植物就不會進行任何作用", "D": "懸浮微粒與風速無關，只由樹木數量決定"}, "樹葉表面可能攔截部分粒狀物，但通風不足與排放持續會使污染物累積；植物作用不能取代風場與排放條件。", "多因素題把攔截效果和污染物輸送、來源分開分析。", ["先確認觀察到的降低可能與樹葉攔截有關。", "再找出無風時通風變弱、排放仍存在。", "將兩種作用放在同一個因果模型。", "避免把樹木數量當成唯一決定因素。", "所以選 A。"], "hard"),
    make(7, "校園內一處有樹區比無樹區涼，但有樹區也較靠近水池。要判斷降溫是否主要來自植物，應如何改進？", {"A": "找出遠離水池但遮蔭、地表材質與風向相近的對照點，並在相同時段重複量測", "B": "只增加更多樹木，不需要新的對照", "C": "把水池因素直接忽略，因為植物一定是主因", "D": "只在最熱的一天測量一次即可"}, "水池蒸發與水體熱容量可能影響溫度，需找條件相近但不靠水池的對照點，並固定時段重複量測。", "找替代原因後，透過空間配對與時間重複降低混淆。", ["指出水池是可能的替代解釋。", "尋找不靠水池但其他條件相近的對照點。", "固定測量時段、高度、材質與風向條件。", "重複資料後再估計植物遮蔭或蒸散的效果。", "所以選 A。"], "medium"),
    make(8, "下列哪項結論最符合科學證據的適用範圍？", {"A": "在本次測量的時間、地點與天氣條件下，有樹區地表溫度較低；仍需更多資料判斷其他季節", "B": "只要一個樹下測點較涼，就能證明所有森林都能降溫", "C": "有植被表示所有空氣污染都會消失", "D": "雨後沒有積水就代表植物吸收了全部雨水"}, "科學結論要帶有測量時間、地點與條件；單一測點不能外推所有季節與環境，也不能把不積水等同全部被植物吸收。", "答案檢查『資料支持到哪裡』，把超出測量範圍的字句刪掉。", ["標出實際測量的地點、時間與天氣。", "只描述資料直接支持的地表溫度差。", "列出季節、植物種類與風場等尚未測因素。", "排除全森林、所有污染與全部雨水等過度概括。", "所以選 A。"], "easy"),
    make(9, "若要同時研究植物分布對水流、氣溫與空氣品質的影響，最適合的資料組合為何？", {"A": "雨後逕流與入滲量、標準高度的地表溫度、同時段多測點粒狀物濃度及風場紀錄", "B": "只記錄植物種類，不記錄任何環境數值", "C": "只測空氣品質，就推論水流與溫度也一定改善", "D": "把三種指標在不同月份各測一次，再直接比較數值"}, "三條作用路徑需要不同但可對照的指標：水流看逕流／入滲，熱看固定高度溫度，空氣看粒狀物與風場；不同月份單次資料難以直接比較。", "整合題先為每個問題配置直接指標，再檢查時間與空間可比性。", ["把水流問題配對逕流、入滲與土壤含水。", "把熱問題配對固定高度與時間的溫度。", "把空氣品質配對粒狀物、風向與多測點。", "確認資料需在可比較的時間與條件下收集。", "所以選 A。"], "hard"),
    make(10, "要避免把『有植物』當成萬用環境改善答案，哪種報告結構最完整？", {"A": "先呈現測量資料，再說明可能機制與替代原因，最後限定季節、位置、植物種類與管理條件", "B": "先下結論，再只挑支持植物有益的資料", "C": "只放一張綠地照片，不提供測量方法", "D": "把所有環境指標都歸因於植物，不討論風向、地表與排放"}, "完整報告要區分資料、機制推論與替代解釋，並寫明結果的適用條件，才能避免綠化口號取代科學判讀。", "報告題採『資料—機制—替代原因—適用範圍』四段檢核。", ["先列出水、熱與空氣的測量結果。", "針對每項資料提出植物可能作用的機制。", "補上風向、地表材質、坡度與排放等替代原因。", "限定結論的季節、位置、植物種類與管理條件。", "所以選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
